#!/usr/bin/env tsx
/**
 * Generate What the Top-Level Help Shows for Each Route
 *
 * `sentry`, `sentry help` and `sentry --help` load only the `help` command
 * and stand in for every other visible route (`src/root-help-routes.ts`).
 * Names, hidden flags and briefs come from `COMMAND_MANIFEST`. The rest
 * derives from code: a route group's visible subcommands, and a command's
 * usage line and placeholder, which come from its flags and positionals.
 * This script reads them from the loaded route tree.
 *
 * The output is gitignored and regenerated by `generate:docs`, which runs as
 * part of `dev`, `build`, `bundle`, `typecheck`, and `test`.
 *
 * Usage:   tsx script/generate-top-level-routes.ts
 * Output:  src/generated/top-level-routes.json
 */

import { mkdirSync } from "node:fs";
import { access, writeFile } from "node:fs/promises";

// Bootstrap: skill-content stub (same pattern as
// generate-completion-targets.ts). The route tree transitively imports
// skill-content.ts, which may not exist yet on a fresh checkout. Must run
// before the dynamic import below.
const SKILL_CONTENT_PATH = "src/generated/skill-content.ts";
const SKILL_CONTENT_STUB =
  "export const SKILL_FILES: [string, string][] = [];\n";
const skillContentExists = await access(SKILL_CONTENT_PATH).then(
  () => true,
  () => false,
);
if (!skillContentExists) {
  mkdirSync("src/generated", { recursive: true });
  await writeFile(SKILL_CONTENT_PATH, SKILL_CONTENT_STUB);
}

const { app, routes } = await import("../src/app.js");
const { describeTopLevelRoutes } = await import("./lib/top-level-routes.js");

const OUTPUT_PATH = "src/generated/top-level-routes.json";

const described = describeTopLevelRoutes(routes, app.config.documentation);

mkdirSync("src/generated", { recursive: true });
await writeFile(OUTPUT_PATH, `${JSON.stringify(described, null, 2)}\n`);

console.log(
  `Generated ${OUTPUT_PATH} (${Object.keys(described).length} routes)`,
);
